from constants import *
import os
import urllib
import mimetypes
import logging

logger = logging.getLogger(APP_NAME)

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None
            self.type = None

    @staticmethod
    def get_objects(path):
        objects = []
        object_paths = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                object = Object(object_path)
                objects.append(object)
                object_paths.append(object_path)

        _update_mimetypes(objects, object_paths)

        return objects


def _update_mimetypes(objects, object_paths):
    mime_types = mimetypes.guess_type
    for object, object_path in zip(objects, object_paths):
        if object.type is None:
            url = urllib.pathname2url(object.path)
            try:
                object.type = mime_types(url)[0]
            except:
                logger.warning('Cannot determine file type of "%s"' % object.path)


