from __future__ import annotations
from typing import TypeVar, Optional

T = TypeVar("T")


class SinglyLinkedList:
    class Node:
        def __init__(self, value: T, next_node: Optional[SinglyLinkedList.Node] = None):
            self.value = value
            self.next = next_node

    def __init__(self):
        self.head: Optional[SinglyLinkedList.Node] = None
        self.tail: Optional[SinglyLinkedList.Node] = None
        self.length = 0

    def __len__(self) -> int:
        return self.length

    def __iter__(self):
        node = self.head
        while node is not None:
            yield node
            node = node.next

    def append(self, value: T) -> None:
        new_node = SinglyLinkedList.Node(value)
        if self.head is None:
            self.head = new_node
        else:
            self.tail.next = new_node
        self.tail = new_node
        self.length += 1

    def remove_next(self, node: SinglyLinkedList.Node) -> None:
        if node.next is self.tail:
            self.tail = node
        node.next = node.next.next
        self.length -= 1


